TABLE  <- { atom->atom, var->var, bot->falsum, top->verum,
            and->conj, arr->impl, box->box, mu->mu }
INVERSE <- inverse map of TABLE

function TRANSLATE(node, table):
    kind <- table[node.kind]
    if node has no children:      return Node(kind, payload of node)
    if node has one child:        return Node(kind, TRANSLATE(node.left, table))
    return Node(kind, TRANSLATE(node.left, table), TRANSLATE(node.right, table))

function ROUND_TRIP_OK(A):
    F <- TRANSLATE(A, TABLE)                 // tau(A)
    return TRANSLATE(F, INVERSE) = A         // sigma(tau(A)) = A
       and TRANSLATE(TRANSLATE(F, INVERSE), TABLE) = F

function CERTIFY(max_size):
    for s <- 1 to max_size:
        for each code A of size s:
            assert ROUND_TRIP_OK(A)

algorithms.code:
"""Constructor-wise translation between reflective codes and modal fixed-point
formulas, with round-trip certification.

Both translations are single bottom-up passes; certifying a round trip on a code
of n nodes costs O(n)."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Iterator, Optional, Tuple

REFLECTIVE_KINDS = ("atom", "var", "bot", "top", "and", "arr", "box", "mu")
MODAL_KINDS = ("atom", "var", "falsum", "verum", "conj", "impl", "box", "mu")

TO_MU: Dict[str, str] = dict(zip(REFLECTIVE_KINDS, MODAL_KINDS))
FROM_MU: Dict[str, str] = {v: k for k, v in TO_MU.items()}


@dataclass(frozen=True)
class Node:
    """A syntax tree in either grammar; `kind` selects the constructor."""

    kind: str
    atom: Optional[str] = None
    index: Optional[int] = None
    left: Optional["Node"] = None
    right: Optional["Node"] = None


def translate(node: Node, table: Dict[str, str]) -> Node:
    """Relabel every constructor through `table`, recursing structurally."""
    kind = table[node.kind]
    if node.left is None:
        return Node(kind, atom=node.atom, index=node.index)
    if node.right is None:
        return Node(kind, left=translate(node.left, table))
    return Node(
        kind,
        left=translate(node.left, table),
        right=translate(node.right, table),
    )


def to_mu(node: Node) -> Node:
    """Reflective proposition -> modal fixed-point formula."""
    return translate(node, TO_MU)


def from_mu(node: Node) -> Node:
    """Modal fixed-point formula -> reflective proposition."""
    return translate(node, FROM_MU)


def round_trip_ok(node: Node) -> bool:
    """Certify sigma(tau(A)) == A and tau(sigma(tau(A))) == tau(A)."""
    forward = to_mu(node)
    return from_mu(forward) == node and to_mu(from_mu(forward)) == forward


def enumerate_codes(size: int, atoms: Tuple[str, ...] = ("p",),
                    variables: int = 1) -> Iterator[Node]:
    """All reflective codes with exactly `size` constructor nodes."""
    if size <= 0:
        return
    if size == 1:
        for p in atoms:
            yield Node("atom", atom=p)
        for n in range(variables):
            yield Node("var", index=n)
        yield Node("bot")
        yield Node("top")
        return
    for sub in enumerate_codes(size - 1, atoms, variables):
        yield Node("box", left=sub)
        yield Node("mu", left=sub)
    for split in range(1, size - 1):
        for left in enumerate_codes(split, atoms, variables):
            for right in enumerate_codes(size - 1 - split, atoms, variables):
                yield Node("and", left=left, right=right)
                yield Node("arr", left=left, right=right)


if __name__ == "__main__":
    checked = 0
    for s in range(1, 6):
        for code in enumerate_codes(s):
            assert round_trip_ok(code)
            checked += 1
    print(f"round trips certified on {checked} codes of size <= 5")

