function BOX(frame, P):
    return { w : successors(frame, w) subset of P }

function WITNESSES(frame, P):
    B1 <- BOX(frame, P)
    B2 <- BOX(frame, B1)
    return B1 \ B2

function IS_TRANSITIVE(frame):
    for all a, b with a -> b:
        for all c with b -> c:
            if not (a -> c): return false
    return true

function SURVEY(n):
    for each of the 2^(n^2) frames F on {0,...,n-1}:
        t <- IS_TRANSITIVE(F)
        for each of the 2^n propositions P:
            if WITNESSES(F, P) nonempty:
                assert not t          // the transitivity theorem
                record (F, P, witness); break

algorithms.code:
"""Exhaustive reflection-witness search on finite Kripke frames.

A reflection witness for a proposition P is a world where P is provable but not
provably provable, i.e. a member of  Box P \\ Box Box P.  Evaluating Box costs
O(n^2); the exhaustive sweep over all frames and propositions on n worlds costs
O(2^(n^2) * 2^n * n^2), which is practical up to n = 3 (512 * 8 relations/props)
and, with symmetry reduction, n = 4."""

from __future__ import annotations

from itertools import product
from typing import Dict, FrozenSet, Iterator, List, Tuple

Frame = Dict[int, FrozenSet[int]]


def box(frame: Frame, prop: FrozenSet[int]) -> FrozenSet[int]:
    """Box P = { w : every successor of w lies in P }."""
    return frozenset(w for w, succ in frame.items() if succ <= prop)


def is_transitive(frame: Frame) -> bool:
    """a -> b and b -> c imply a -> c?"""
    return all(c in frame[a] for a in frame for b in frame[a] for c in frame[b])


def witnesses(frame: Frame, prop: FrozenSet[int]) -> FrozenSet[int]:
    """Worlds satisfying Box P but not Box Box P."""
    first = box(frame, prop)
    return frozenset(first - box(frame, first))


def all_frames(n: int) -> Iterator[Frame]:
    """All 2^(n^2) frames on {0, ..., n-1}."""
    worlds = list(range(n))
    for bits in product((False, True), repeat=n * n):
        yield {w: frozenset(v for v in worlds if bits[w * n + v]) for w in worlds}


def all_props(n: int) -> Iterator[FrozenSet[int]]:
    """All 2^n propositions on {0, ..., n-1}."""
    for bits in product((False, True), repeat=n):
        yield frozenset(w for w in range(n) if bits[w])


def survey(n: int) -> Tuple[int, int, int, List[Tuple[Frame, FrozenSet[int], int]]]:
    """Return (#frames, #transitive, #frames with a witness, sample witnesses)."""
    total = 0
    transitive = 0
    with_witness = 0
    samples: List[Tuple[Frame, FrozenSet[int], int]] = []
    for frame in all_frames(n):
        total += 1
        trans = is_transitive(frame)
        transitive += int(trans)
        found = False
        for prop in all_props(n):
            wit = witnesses(frame, prop)
            if wit:
                found = True
                assert not trans, "transitivity must forbid witnesses"
                if len(samples) < 3:
                    samples.append((frame, prop, min(wit)))
                break
        with_witness += int(found)
    return total, transitive, with_witness, samples


if __name__ == "__main__":
    for n in (1, 2, 3):
        total, trans, wit, samples = survey(n)
        print(f"n={n}: frames={total} transitive={trans} with-witness={wit}")
        for frame, prop, w in samples:
            edges = sorted((a, b) for a in frame for b in frame[a])
            print(f"    edges={edges} P={sorted(prop)} witness at world {w}")

"""Polarity analysis: deciding the positivity guard for fixed-point codes.

A single traversal carries a polarity flag, initialised positive, preserved by
conjunction, by necessity, by the fixed-point binder and by the consequent of an
implication, and flipped by the antecedent of an implication.  A code mu X. A is
guarded exactly when every free occurrence of X in A is met with a positive flag.
Cost: O(n) in the size of the code.  Guardedness is precisely the condition under
which the induced set operator is monotone, so that Knaster-Tarski supplies a
least fixed point."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, FrozenSet, List, Optional, Set


@dataclass(frozen=True)
class Node:
    """Reflective code: kind in {atom, var, bot, top, and, arr, box, mu}."""

    kind: str
    atom: Optional[str] = None
    index: Optional[int] = None
    left: Optional["Node"] = None
    right: Optional["Node"] = None


def occurs_positively(body: Node, depth: int = 0, positive: bool = True) -> bool:
    """Every occurrence of the variable bound at `depth` is positive?"""
    if body.kind == "var":
        return positive if body.index == depth else True
    if body.kind in ("atom", "bot", "top"):
        return True
    if body.kind == "and":
        return occurs_positively(body.left, depth, positive) and occurs_positively(
            body.right, depth, positive
        )
    if body.kind == "arr":
        return occurs_positively(body.left, depth, not positive) and occurs_positively(
            body.right, depth, positive
        )
    if body.kind == "box":
        return occurs_positively(body.left, depth, positive)
    return occurs_positively(body.left, depth + 1, positive)  # mu


def least_fixed_point(
    operator: Callable[[FrozenSet[int]], FrozenSet[int]], worlds: Set[int]
) -> Optional[FrozenSet[int]]:
    """Kleene iteration from the empty set; None if it fails to converge.

    For a monotone operator on a finite powerset lattice the iteration
    stabilises after at most |worlds| steps and returns the least fixed point.
    """
    current: FrozenSet[int] = frozenset()
    for _ in range(len(worlds) + 1):
        nxt = operator(current)
        if nxt == current:
            return current
        if not current <= nxt:  # non-monotone behaviour detected
            return None
        current = nxt
    return None


if __name__ == "__main__":
    unguarded = Node("arr", left=Node("var", index=0), right=Node("bot"))
    guarded = Node("box", left=Node("var", index=0))
    print("mu X. (X -> bot) guarded?", occurs_positively(unguarded))
    print("mu X. box X   guarded?", occurs_positively(guarded))

    worlds = {0, 1, 2}
    chain = {2: frozenset({1}), 1: frozenset({0}), 0: frozenset()}

    def box_op(s: FrozenSet[int]) -> FrozenSet[int]:
        return frozenset(w for w, succ in chain.items() if succ <= s)

    def negation_op(s: FrozenSet[int]) -> FrozenSet[int]:
        return frozenset(worlds - set(s))

    print("least fixed point of box on the chain:", sorted(least_fixed_point(box_op, worlds) or []))
    print("least fixed point of complement:", least_fixed_point(negation_op, worlds))

